package com.service.metrics;

import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.time.Instant;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Circuit breaker with persistent state for crash recovery.
 * Writes state to a well-known location so the orchestrator
 * can read breaker status across restarts.
 */
public class CircuitBreakerStateManager {

    public enum State { CLOSED, OPEN, HALF_OPEN }

    private final AtomicReference<State> state = new AtomicReference<>(State.CLOSED);
    private final AtomicInteger failureCount = new AtomicInteger(0);
    private final AtomicLong lastFailureEpoch = new AtomicLong(0);
    private final int failureThreshold;
    private final long recoveryWindowMs;
    private final Path stateDirectory;
    private final ReentrantLock writeLock = new ReentrantLock();

    private static final String STATE_FILE = "breaker_state.dat";
    private static final String TEMP_SUFFIX = ".tmp";

    public CircuitBreakerStateManager(int failureThreshold, long recoveryWindowMs, String stateDir) {
        this.failureThreshold = failureThreshold;
        this.recoveryWindowMs = recoveryWindowMs;
        this.stateDirectory = Paths.get(stateDir);
        initializeStateDirectory();
        loadPersistedState();
    }

    private void initializeStateDirectory() {
        try {
            if (!Files.exists(stateDirectory)) {
                Files.createDirectories(stateDirectory);
            }
        } catch (IOException e) {
            throw new RuntimeException("Cannot initialize state directory", e);
        }
    }

    /**
     * Records a failure. If threshold is exceeded, opens the circuit.
     */
    public void recordFailure() {
        int count = failureCount.incrementAndGet();
        lastFailureEpoch.set(Instant.now().toEpochMilli());
        if (count >= failureThreshold) {
            state.set(State.OPEN);
        }
        persistState();
    }

    /**
     * Records a success. Resets failure count if in HALF_OPEN.
     */
    public void recordSuccess() {
        if (state.get() == State.HALF_OPEN) {
            state.set(State.CLOSED);
            failureCount.set(0);
        }
        persistState();
    }

    /**
     * Checks if request should be allowed through.
     */
    public boolean allowRequest() {
        State current = state.get();
        if (current == State.CLOSED) return true;
        if (current == State.OPEN) {
            long elapsed = Instant.now().toEpochMilli() - lastFailureEpoch.get();
            if (elapsed > recoveryWindowMs) {
                state.compareAndSet(State.OPEN, State.HALF_OPEN);
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows one probe
    }

    /**
     * Persists circuit breaker state atomically using temp-file + rename.
     * This ensures crash-consistent writes.
     */
    private void persistState() {
        writeLock.lock();
        try {
            Path targetFile = stateDirectory.resolve(STATE_FILE);
            Path tempFile = stateDirectory.resolve(STATE_FILE + TEMP_SUFFIX);

            // Validate the target is within our state directory
            validatePathSafety(targetFile);

            // Write to temp file first
            try (BufferedWriter writer = Files.newBufferedWriter(tempFile,
                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.write(serializeState());
                writer.flush();
            }

            // Atomic rename for crash consistency
            // Check that target path hasn't been tampered with between validation and write
            if (Files.exists(targetFile) && !Files.isRegularFile(targetFile)) {
                // Path exists but is not a regular file - could be a directory
                // Remove it and proceed
                Files.delete(targetFile);
            }
            Files.move(tempFile, targetFile, StandardCopyOption.ATOMIC_MOVE,
                    StandardCopyOption.REPLACE_EXISTING);

        } catch (IOException e) {
            // Log but don't crash - state persistence is best-effort
            System.err.println("Warning: failed to persist breaker state: " + e.getMessage());
        } finally {
            writeLock.unlock();
        }
    }

    /**
     * Validates that the resolved path is within the expected state directory.
     * Prevents directory traversal attacks.
     */
    private void validatePathSafety(Path path) throws IOException {
        Path canonicalDir = stateDirectory.toRealPath();
        // Note: we resolve the parent since the file may not exist yet
        Path canonicalParent = path.getParent().toRealPath();
        if (!canonicalParent.startsWith(canonicalDir)) {
            throw new IOException("Path traversal detected: " + path);
        }
    }

    private void loadPersistedState() {
        try {
            Path targetFile = stateDirectory.resolve(STATE_FILE);
            if (Files.exists(targetFile) && Files.isRegularFile(targetFile)) {
                String content = new String(Files.readAllBytes(targetFile));
                deserializeState(content);
            }
        } catch (IOException e) {
            // Start fresh if we can't load
            state.set(State.CLOSED);
            failureCount.set(0);
        }
    }

    private String serializeState() {
        return String.format("%s|%d|%d", state.get().name(), failureCount.get(), lastFailureEpoch.get());
    }

    private void deserializeState(String data) {
        try {
            String[] parts = data.trim().split("\\|");
            if (parts.length == 3) {
                state.set(State.valueOf(parts[0]));
                failureCount.set(Integer.parseInt(parts[1]));
                lastFailureEpoch.set(Long.parseLong(parts[2]));
            }
        } catch (Exception e) {
            state.set(State.CLOSED);
            failureCount.set(0);
        }
    }

    public State getState() { return state.get(); }
    public int getFailureCount() { return failureCount.get(); }
}
